const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict'),{pathToFileURL}=require('node:url'),crypto=require('node:crypto');const {chromium}=require(process.env.SCIMUX_E2E_PLAYWRIGHT);
(async()=>{const source=process.argv[2],out=process.argv[3];fs.mkdirSync(out,{recursive:true,mode:0o700});const {guestMessageHTML}=await import(pathToFileURL(path.join(source,'web/js/team-guest.js')));const key=['a'.repeat(32),'b'.repeat(32),'c'.repeat(16),'d'.repeat(16)].join('/'),bytes=Buffer.from('89504e470d0a1a0a','hex');const file={id:'0123456789abcdef',sha256:crypto.createHash('sha256').update(bytes).digest('hex'),size:bytes.length,name:'synthetic-invalid.png',mime:'image/png'};const markup=guestMessageHTML({seq:1,anchor:0,author:'b'.repeat(32),at:'2026-01-01T00:00:00Z',text:'',attachments:[file],_peopleRetained:{[file.id]:true}},{},'a'.repeat(32),{},'','',key,p=>p);const links=fs.readFileSync(path.join(source,'web/index.html'),'utf8').match(/<link rel="stylesheet" href="[^"]+">/g).join('\n');let previews=0;const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://fixture'),name=url.pathname;if(name==='/'){res.setHeader('Content-Type','text/html');res.end(`<!doctype html><html><head>${links}</head><body><section id="chat" style="display:flex"><div id="msgwrap"><div id="msgs"></div></div></section><script type="module">import {createChatFeature} from '/js/chat.js';const msgs=document.querySelector('#msgs');const feature=createChatFeature({document,window,roots:{msgs},assetURL:p=>p});feature.bind();msgs.innerHTML=${JSON.stringify(markup)};window.ready=true;</script></body></html>`);return;}if(/^\/(css|js)\/[a-z0-9-]+\.(css|js)$/.test(name)){res.setHeader('Content-Type',name.endsWith('.js')?'text/javascript':'text/css');res.end(fs.readFileSync(path.join(source,'web',name)));return;}if(name.includes('/attachments/')){if(url.searchParams.get('preview')==='1'){previews++;res.writeHead(415,{'Content-Type':'application/json'});res.end('{"error":"preview_unsupported"}');return;}res.writeHead(200,{'Content-Type':'application/octet-stream','Content-Disposition':'attachment; filename="synthetic-invalid.png"'});res.end(bytes);return;}res.writeHead(404);res.end();});await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));let browser;try{browser=await chromium.launch();const page=await browser.newPage();await page.goto('http://127.0.0.1:'+server.address().port,{waitUntil:'networkidle'});await page.waitForFunction(()=>window.ready===true);assert.equal(previews,1);const sample=await page.locator('#msgs').evaluate(el=>({text:el.textContent,html:el.innerHTML,downloadLinks:el.querySelectorAll('a[download]').length,thumbnails:el.querySelectorAll('.attthumb').length}));console.log(JSON.stringify(sample));fs.writeFileSync(path.join(out,'result.json'),JSON.stringify(sample,null,2));await page.screenshot({path:path.join(out,'invalid-preview.png'),fullPage:true});assert.ok(sample.text.includes(file.name)&&sample.downloadLinks>0,'retained file with refused safe preview must retain its filename and an actual download control');}finally{if(browser)await browser.close();await new Promise(resolve=>server.close(resolve));}})().catch(e=>{console.error(e.message);process.exitCode=1});
